/* Convert a 1-D Python sequence of numbers to a malloc'd double buffer. */
static double* sequence_to_doubles(PyObject *seq, Py_ssize_t *out_len) {
    PyObject *fast = PySequence_Fast(seq, "input must be a sequence of numbers");
    if (!fast) return NULL;
    Py_ssize_t len = PySequence_Fast_GET_SIZE(fast);
    double *buf = (double *)malloc((size_t)len * sizeof(double));
    if (!buf) { Py_DECREF(fast); PyErr_NoMemory(); return NULL; }
    for (Py_ssize_t i = 0; i < len; i++) {
        PyObject *item = PySequence_Fast_GET_ITEM(fast, i);
        double v;
        if (PyFloat_CheckExact(item)) {
            v = PyFloat_AS_DOUBLE(item);
        } else {
            v = PyFloat_AsDouble(item);
            if (v == -1.0 && PyErr_Occurred()) {
                free(buf); Py_DECREF(fast); return NULL;
            }
        }
        buf[i] = v;
    }
    Py_DECREF(fast);
    *out_len = len;
    return buf;
}

