static int compute_risk_from_lists(double *x, Py_ssize_t n, PyObject *cov_seq, double *risk_squared_out) {
    PyObject *fast = PySequence_Fast(cov_seq, "cov_matrix must be a 2-D sequence");
    if (!fast) return -1;
    Py_ssize_t n_rows = PySequence_Fast_GET_SIZE(fast);
    if (n_rows != n) { error }
    double risk_squared = 0.0;
    for (i = 0; i < n; i++) {
        PyObject *row = PySequence_Fast_GET_ITEM(fast, i);
        PyObject *rfast = PySequence_Fast(row, "cov row must be a sequence");
        if (!rfast) { Py_DECREF(fast); return -1; }
        if (PySequence_Fast_GET_SIZE(rfast) != n) { error; }
        double row_sum = 0.0;
        for (j = 0; j < n; j++) {
            PyObject *item = PySequence_Fast_GET_ITEM(rfast, j);
            double v = PyFloat_CheckExact(item) ? PyFloat_AS_DOUBLE(item) : PyFloat_AsDouble(item);
            row_sum += v * x[j];
        }
        Py_DECREF(rfast);
        risk_squared += x[i] * row_sum;
    }
    Py_DECREF(fast);
    *risk_squared_out = risk_squared;
    return 0;
}
```

