/*
 * High-performance portfolio calculations using a C extension.
 *
 * Uses the NumPy C API for zero-copy NumPy array access, and a tight
 * C-level conversion loop for plain Python sequences (list of lists, ...),
 * which is far faster than converting in Python.
 *
 *   portfolio_risk_c(weights, cov)       -> sqrt(x^T * S * x)
 *   portfolio_return_c(weights, returns) -> x^T * r
 *
 * Accepts either NumPy arrays or plain Python sequences (lists/tuples).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Extract a Python number as a double. Returns 0 on success, -1 on error. */
static int item_to_double(PyObject *item, double *out) {
    if (PyFloat_CheckExact(item)) {
        *out = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

/*
 * Convert a 1-D Python sequence (list/tuple/...) of numbers to a malloc'd
 * double buffer. Returns NULL on error (with exception set).
 */
static double *sequence_to_doubles(PyObject *seq, Py_ssize_t *out_len) {
    PyObject *fast = PySequence_Fast(seq, "input must be a sequence of numbers");
    if (fast == NULL)
        return NULL;

    Py_ssize_t len = PySequence_Fast_GET_SIZE(fast);
    double *buf = (double *)malloc(((size_t)len > 0 ? (size_t)len : 1) * sizeof(double));
    if (buf == NULL) {
        Py_DECREF(fast);
        PyErr_NoMemory();
        return NULL;
    }

    for (Py_ssize_t i = 0; i < len; i++) {
        if (item_to_double(PySequence_Fast_GET_ITEM(fast, i), &buf[i]) != 0) {
            free(buf);
            Py_DECREF(fast);
            return NULL;
        }
    }

    Py_DECREF(fast);
    *out_len = len;
    return buf;
}
