    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *row = PySequence_Fast_GET_ITEM(fast, i);
        PyObject *rfast = PySequence_Fast(row, "cov_matrix rows must be sequences");
        if (!rfast) { Py_DECREF(fast); return -1; }
        if (PySequence_Fast_GET_SIZE(rfast) != n) {
            Py_DECREF(rfast); Py_DECREF(fast);
            PyErr_SetString(PyExc_ValueError, "cov_matrix rows must have the same length as weights");
            return -1;
        }
        double row_sum = 0.0;
        for (Py_ssize_t j = 0; j < n; j++) {
            double v;
            if (item_to_double(PySequence_Fast_GET_ITEM(rfast, j), &v) != 0) {
                Py_DECREF(rfast); Py_DECREF(fast);
                return -1;
            }
            row_sum += v * x[j];
        }
        Py_DECREF(rfast);
        risk_squared += x[i] * row_sum;
    }
    Py_DECREF(fast);
    *risk_squared_out = risk_squared;
    return 0;
