 *
 *   portfolio_risk_c(weights, cov)       -> sqrt(x^T * S * x)
 *   portfolio_return_c(weights, returns) -> x^T * r
 *
 * Inputs may be NumPy arrays (handled through the NumPy C API with
 * zero-copy access when the array is already C-contiguous float64) or
 * plain Python sequences (lists/tuples of numbers, or nested lists for
 * the covariance matrix).  Plain sequences are converted with tight
 * C-level loops, which is far faster than doing the conversion in
 * Python.  The matrix product is fused with the conversion pass so the
 * whole covariance matrix never has to be materialized as a second
 * copy, and the accumulation order matches the Python baseline exactly
 * (row-major j loop per row, then i loop for the dot product).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/*
 * Extract a Python number as a double.
 * Returns 0 on success, -1 on error (exception set).
 */
static int item_to_double(PyObject *item, double *out) {
    if (PyFloat_CheckExact(item)) {
        *out = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

/*
 * Convert a 1-D Python sequence of numbers into a malloc'd double buffer.
 * Returns NULL on error (exception set).  Caller must free() the result.
 */
static double *sequence_to_doubles(PyObject *seq, Py_ssize_t *out_len) {
    PyObject *fast;
    Py_ssize_t len, i;
    double *buf;

    fast = PySequence_Fast(seq, "input must be a sequence of numbers");
    if (fast == NULL)
        return NULL;

    len = PySequence_Fast_GET_SIZE(fast);
    buf = (double *)malloc((size_t)(len > 0 ? len : 1) * sizeof(double));
    if (buf == NULL) {
        Py_DECREF(fast);
        PyErr_NoMemory();
        return NULL;
    }

    for (i = 0; i < len; i++) {
        if (item_to_double(PySequence_Fast_GET_ITEM(fast, i), &buf[i]) != 0) {
            free(buf);
            Py_DECREF(fast);
            return NULL;
        }
    }

    Py_DECREF(fast);
    *out_len = len;
    return buf;
}

/*
 * Compute risk_squared = x^T * S * x by walking a Python 2-D sequence
 * (e.g. a list of lists) directly in C, row by row, without materializing
 * the full matrix as a second buffer.
 *
 * Accumulation order matches the Python baseline:
 *   for i: row_sum = sum_j S[i][j] * x[j];  risk_squared += x[i] * row_sum
 *
 * Returns 0 on success, -1 on error (exception set).
 */
static int fused_risk_from_sequence(const double *x, Py_ssize_t n,
                                    PyObject *cov_obj, double *risk_squared_out) {
    PyObject *fast, *row, *rfast;
    Py_ssize_t i, j;
    double risk_squared, row_sum, v;

    fast = PySequence_Fast(cov_obj, "cov_matrix must be a 2-D sequence");
    if (fast == NULL)
        return -1;

    if (PySequence_Fast_GET_SIZE(fast) != n) {
        Py_DECREF(fast);
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must have the same dimensions as weights");
        return -1;
    }

    risk_squared = 0.0;
    for (i = 0; i < n; i++) {
        row = PySequence_Fast_GET_ITEM(fast, i);
        rfast = PySequence_Fast(row, "cov_matrix rows must be sequences");
        if (rfast == NULL) {
            Py_DECREF(fast);
            return -1;
        }
        if (PySequence_Fast_GET_SIZE(rfast) != n) {
            Py_DECREF(rfast);
            Py_DECREF(fast);
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix rows must have the same length as weights");
            return -1;
        }

        row_sum = 0.0;
        for (j = 0; j < n; j++) {
            if (item_to_double(PySequence_Fast_GET_ITEM(rfast, j), &v) != 0) {
                Py_DECREF(rfast);
                Py_DECREF(fast);
                return -1;
            }
            row_sum += v * x[j];
        }
        Py_DECREF(rfast);
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(fast);
    *risk_squared_out = risk_squared;
    return 0;
}

