            return NULL;
        if (PyArray_NDIM(weights_array) != 1) {
            PyErr_SetString(PyExc_ValueError, "weights must be a 1-D array");
            goto fail;
        }
        n = PyArray_DIM(weights_array, 0);
        x = (double *)PyArray_DATA(weights_array);
    } else {
        x = sequence_to_doubles(weights_obj, &n);
        if (x == NULL)
            return NULL;
    }

    /* returns -> contiguous float64 */
    if (PyArray_Check(returns_obj)) {
        returns_array = (PyArrayObject *)PyArray_FROM_OTF(
            returns_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (returns_array == NULL)
            goto fail;
        if (PyArray_NDIM(returns_array) != 1) {
            PyErr_SetString(PyExc_ValueError, "expected_returns must be a 1-D array");
            goto fail;
        }
        m = PyArray_DIM(returns_array, 0);
        if (m != n) {
            PyErr_SetString(PyExc_ValueError,
                            "weights and expected_returns must have equal length");
            goto fail;
        }
        r = (double *)PyArray_DATA(returns_array);
    } else {
        r = sequence_to_doubles(returns_obj, &m);
        if (r == NULL)
            goto fail;
        if (m != n) {
            PyErr_SetString(PyExc_ValueError,
                            "weights and expected_returns must have equal length");
            goto fail;
        }
    }

    total_return = 0.0;
    for (i = 0; i < n; i++) {
        total_return += x[i] * r[i];
    }

    result = PyFloat_FromDouble(total_return);

  cleanup:
    if (weights_array != NULL)
        Py_DECREF(weights_array);
    else if (x != NULL)
        free(x);
    if (returns_array != NULL)
        Py_DECREF(returns_array);
    else if (r != NULL)
        free(r);
    return result;

  fail:
    result = NULL;
    goto cleanup;
}

